#!/usr/bin/env node
// Builds a self-contained static HTML page for reviewing candidate character
// voice takes side-by-side with the character's portrait and dialogue line,
// so audio candidates generated by scripts/generate-voice.mjs can be
// compared in a browser instead of one-at-a-time as chat attachments.
//
// Usage:
//   node scripts/build-voice-review.mjs
//
// Regenerate this any time new audio lands in tmp/voice-previews/<slug>/ or
// assets/audio/voices/<slug>/ — it just re-scans the filesystem.
//
// View it:
//   python3 -m http.server 8000
//   # then open http://127.0.0.1:8000/tmp/voice-review/index.html

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { CHARACTERS } from "./generate-voice.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const previewDir = path.join(root, "tmp/voice-previews");
const voiceDir = path.join(root, "assets/audio/voices");
const assetsDir = path.join(root, "assets/generated");
const registryPath = path.join(root, "scripts/voice-registry.json");
const outDir = path.join(root, "tmp/voice-review");
const outFile = path.join(outDir, "index.html");

function slugify(text) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

function escapeHtml(text) {
  return String(text).replace(/[&<>"']/g, (char) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[char]));
}

function loadRegistry() {
  if (!fs.existsSync(registryPath)) return {};
  return JSON.parse(fs.readFileSync(registryPath, "utf8"));
}

// Portrait naming in assets/generated/ is inconsistent across the roster:
// some characters use their full slug (sorin-dask-face.png), some use only
// the first name (mara-face.png for mara-velen), some use a fuller label
// slug (director-vel-ordan-face.png for director-vel). Try all three.
function findPortrait(slug, label) {
  const firstToken = slug.split("-")[0];
  const candidates = [slug, slugify(label), firstToken];
  for (const suffix of ["face", "visitor"]) {
    for (const candidate of candidates) {
      const file = path.join(assetsDir, `${candidate}-${suffix}.png`);
      if (fs.existsSync(file)) return `../../assets/generated/${candidate}-${suffix}.png`;
    }
  }
  return null;
}

function listMp3s(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith(".mp3"))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
}

function buildCharacter(slug, character, registry) {
  const resolved = Boolean(registry[slug]?.voice_id);
  const portrait = findPortrait(slug, character.label);
  const finals = listMp3s(path.join(voiceDir, slug)).map((file) => ({
    file,
    src: `../../assets/audio/voices/${slug}/${file}`,
  }));
  const candidates = listMp3s(path.join(previewDir, slug)).map((file) => ({
    file,
    src: `../../tmp/voice-previews/${slug}/${file}`,
  }));
  return {
    slug,
    label: character.label,
    line: character.lines?.question || character.previewText || "",
    portrait,
    resolved,
    voiceId: registry[slug]?.voice_id || null,
    finals,
    candidates,
  };
}

function renderAudioRow({ file, src }, kind) {
  const badge = kind === "final"
    ? '<span class="badge badge-final">FINAL</span>'
    : '<span class="badge badge-candidate">candidate</span>';
  return `
        <li class="take take-${kind}">
          ${badge}
          <code class="take-name">${escapeHtml(file)}</code>
          <audio controls preload="none" src="${escapeHtml(src)}"></audio>
        </li>`;
}

function renderCharacter(data) {
  const portraitHtml = data.portrait
    ? `<img class="portrait" src="${escapeHtml(data.portrait)}" alt="${escapeHtml(data.label)} portrait">`
    : `<div class="portrait portrait-placeholder">no portrait yet</div>`;

  const statusHtml = data.resolved
    ? `<span class="status status-resolved">RESOLVED &mdash; voice_id ${escapeHtml(data.voiceId)}</span>`
    : `<span class="status status-pending">PENDING &mdash; no saved voice yet</span>`;

  const totalAudio = data.finals.length + data.candidates.length;
  const audioHtml = totalAudio === 0
    ? `<p class="no-audio">No audio generated yet.</p>`
    : `<ul class="takes">
${data.finals.map((take) => renderAudioRow(take, "final")).join("")}
${data.candidates.map((take) => renderAudioRow(take, "candidate")).join("")}
      </ul>`;

  return `
    <section class="character${data.resolved ? " is-resolved" : " is-pending"}" id="${escapeHtml(data.slug)}">
      <div class="character-header">
        ${portraitHtml}
        <div class="character-meta">
          <h2>${escapeHtml(data.label)} <span class="slug">${escapeHtml(data.slug)}</span></h2>
          ${statusHtml}
          <p class="line">&ldquo;${escapeHtml(data.line)}&rdquo;</p>
        </div>
      </div>
      ${audioHtml}
    </section>`;
}

function build() {
  const registry = loadRegistry();
  const characters = Object.entries(CHARACTERS).map(([slug, character]) => buildCharacter(slug, character, registry));

  // Pending (unresolved) characters first — those are the ones that still
  // need review/comparison. Resolved characters follow. Alphabetical by
  // label within each group.
  characters.sort((a, b) => {
    if (a.resolved !== b.resolved) return a.resolved ? 1 : -1;
    return a.label.localeCompare(b.label);
  });

  const pendingCount = characters.filter((c) => !c.resolved).length;
  const resolvedCount = characters.length - pendingCount;
  const totalCandidates = characters.reduce((sum, c) => sum + c.candidates.length, 0);
  const totalFinals = characters.reduce((sum, c) => sum + c.finals.length, 0);

  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Red Stamp — Voice Review</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #16181c;
    --panel: #1f2227;
    --panel-border: #2c3038;
    --text: #e8e6e0;
    --text-dim: #9aa0aa;
    --accent-red: #b3382c;
    --accent-brass: #b6913c;
    --final-bg: #2a3320;
    --final-border: #5a7a34;
    --candidate-bg: #26282e;
    --candidate-border: #3a3f47;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 2rem 1.5rem 4rem;
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    line-height: 1.4;
  }
  header {
    max-width: 900px;
    margin: 0 auto 2rem;
  }
  h1 {
    margin: 0 0 0.25rem;
    font-size: 1.6rem;
    letter-spacing: 0.02em;
    border-bottom: 2px solid var(--accent-red);
    padding-bottom: 0.5rem;
  }
  .summary {
    color: var(--text-dim);
    font-size: 0.9rem;
    margin: 0.5rem 0 0;
  }
  .toggle-row {
    margin-top: 0.75rem;
  }
  .toggle-row button {
    background: var(--panel);
    color: var(--text);
    border: 1px solid var(--panel-border);
    border-radius: 4px;
    padding: 0.4rem 0.8rem;
    cursor: pointer;
    font-size: 0.85rem;
  }
  .toggle-row button:hover {
    border-color: var(--accent-brass);
  }
  main {
    max-width: 900px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }
  .character {
    background: var(--panel);
    border: 1px solid var(--panel-border);
    border-radius: 8px;
    padding: 1.25rem;
  }
  .character.is-pending {
    border-left: 4px solid var(--accent-red);
  }
  .character.is-resolved {
    border-left: 4px solid var(--accent-brass);
  }
  body.hide-resolved .character.is-resolved {
    display: none;
  }
  .character-header {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
  }
  .portrait {
    width: 96px;
    height: 96px;
    object-fit: cover;
    border-radius: 6px;
    background: #000;
    flex: none;
    border: 1px solid var(--panel-border);
  }
  .portrait-placeholder {
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-size: 0.7rem;
    color: var(--text-dim);
    padding: 0.5rem;
  }
  .character-meta h2 {
    margin: 0 0 0.35rem;
    font-size: 1.15rem;
  }
  .character-meta .slug {
    font-weight: normal;
    font-size: 0.75rem;
    color: var(--text-dim);
    margin-left: 0.4rem;
  }
  .status {
    display: inline-block;
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.03em;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    margin-bottom: 0.5rem;
  }
  .status-resolved {
    background: var(--final-bg);
    color: #a9d17a;
    border: 1px solid var(--final-border);
  }
  .status-pending {
    background: #3a2323;
    color: #e0a08a;
    border: 1px solid var(--accent-red);
  }
  .line {
    margin: 0.25rem 0 0;
    font-style: italic;
    color: var(--text);
    font-size: 0.95rem;
  }
  .no-audio {
    margin: 0.75rem 0 0;
    color: var(--text-dim);
    font-size: 0.85rem;
  }
  .takes {
    list-style: none;
    margin: 0.9rem 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
  }
  .take {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    flex-wrap: wrap;
    padding: 0.4rem 0.6rem;
    border-radius: 5px;
    border: 1px solid var(--candidate-border);
    background: var(--candidate-bg);
  }
  .take-final {
    background: var(--final-bg);
    border-color: var(--final-border);
  }
  .badge {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    padding: 0.1rem 0.4rem;
    border-radius: 3px;
    flex: none;
  }
  .badge-final {
    background: var(--accent-brass);
    color: #1a1a1a;
  }
  .badge-candidate {
    background: #444;
    color: #ccc;
  }
  .take-name {
    font-size: 0.78rem;
    color: var(--text-dim);
    min-width: 12ch;
  }
  audio {
    height: 32px;
    flex: 1 1 260px;
    min-width: 200px;
  }
  @media (max-width: 520px) {
    .character-header { flex-direction: column; }
    .portrait { width: 100%; height: 160px; }
  }
</style>
</head>
<body>
<header>
  <h1>Red Stamp — Voice Review</h1>
  <p class="summary">${characters.length} characters &middot; ${pendingCount} pending &middot; ${resolvedCount} resolved &middot; ${totalCandidates} candidate takes &middot; ${totalFinals} final line(s) &middot; generated ${new Date().toISOString()}</p>
  <div class="toggle-row">
    <button type="button" onclick="document.body.classList.toggle('hide-resolved')">Toggle: hide resolved characters</button>
  </div>
</header>
<main>
${characters.map(renderCharacter).join("\n")}
</main>
</body>
</html>
`;

  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, html);
  console.log(`Wrote ${path.relative(root, outFile)}`);
  console.log(`${characters.length} characters (${pendingCount} pending, ${resolvedCount} resolved), ${totalCandidates} candidate takes, ${totalFinals} final line(s).`);
}

build();
